// Street address type-ahead for the New customer form (Google Places API
// (New)). ?q=123 colorado&session=<uuid> lists suggestions; ?place_id=…
// &session=<same uuid> returns the picked place as form fields. The page
// keeps one session token from the first keystroke to the pick, so Google
// bills the typing and the pick as one session.
const q = $input.first().json.query || {};
const s = (v) => String(v == null ? '' : v).trim();
const session = s(q.session).replace(/[^A-Za-z0-9_-]/g, '').slice(0, 64);
const placeId = s(q.place_id);
if (placeId) {
  if (!/^[A-Za-z0-9_-]{10,300}$/.test(placeId)) return [{ json: { ok: false, statusCode: 400, body: { error: 'Invalid place_id' } } }];
  return [{ json: { ok: true, mode: 'details', placeId, session } }];
}
const text = s(q.q).slice(0, 200);
if (text.length < 3) return [{ json: { ok: false, statusCode: 400, body: { error: 'Type at least 3 characters' } } }];
const body = { input: text, includedRegionCodes: ['us'], languageCode: 'en' };
if (session) body.sessionToken = session;
return [{ json: { ok: true, mode: 'suggest', body, session } }];

// suggest: { suggestions: [{ place_id, main, secondary }] }
// details: { address, address2, city, state, zip, lat, lng, formatted }
const s = (v) => String(v == null ? '' : v).trim();
const fail = (r, what) => {
  const e = r.error || {};
  const msg = s(e.message || e.description || (typeof e === 'string' ? e : '')) || 'no answer';
  return [{ json: { statusCode: 502, body: { error: 'Google ' + what + ' failed: ' + msg.slice(0, 300) } } }];
};

if ($('Google: autocomplete').isExecuted) {
  const r = $('Google: autocomplete').first().json || {};
  if (r.error) return fail(r, 'address search');
  const suggestions = (r.suggestions || [])
    .map((x) => x.placePrediction)
    .filter((p) => p && p.placeId)
    .map((p) => {
      const f = p.structuredFormat || {};
      return {
        place_id: p.placeId,
        main: s((f.mainText && f.mainText.text) || (p.text && p.text.text)),
        secondary: s(f.secondaryText && f.secondaryText.text),
      };
    });
  return [{ json: { statusCode: 200, body: { suggestions } } }];
}

const r = $('Google: place details').first().json || {};
if (r.error) return fail(r, 'address lookup');
// addressComponents: [{ longText, shortText, types: [...] }]
const comps = r.addressComponents || [];
const get = (type, short) => {
  const c = comps.find((x) => (x.types || []).includes(type));
  return c ? s(short ? c.shortText || c.longText : c.longText || c.shortText) : '';
};
const street = [get('street_number'), get('route', true)].filter(Boolean).join(' ');
// A business result without a street number still has a route; a place
// with neither (a town) leaves the street for the rep.
const sub = get('subpremise');
const city = get('locality') || get('postal_town') || get('sublocality_level_1') || get('sublocality') ||
  get('administrative_area_level_3') || get('neighborhood');
const loc = r.location || {};
return [{
  json: {
    statusCode: 200,
    body: {
      address: street,
      address2: sub ? (/^\d/.test(sub) ? '#' + sub : sub) : '',
      city,
      state: get('administrative_area_level_1', true),
      zip: get('postal_code'),
      lat: isFinite(loc.latitude) ? Number(loc.latitude) : null,
      lng: isFinite(loc.longitude) ? Number(loc.longitude) : null,
      formatted: s(r.formattedAddress),
    },
  },
}];
